-- 033_blog_i18n_translations.sql
-- Woody blog 9 dil cevirisi (en, de, ar, fr, ru, es, it, nl, pt-br) x 13 yazi = 117 satir.
-- Kaynak: blog_posts_i18n locale='tr' (13 yazi). AI ceviri + dogrulama (id/slug/HTML yapi korundu).
-- 024_blog.sql'den SONRA calisir (blog_posts + tr/en taban satirlari onceden var).
-- Idempotent: ON DUPLICATE KEY UPDATE. EN stub satirlari tam ceviriyle guncellenir.
-- Uretildi: 2026-06-18

ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `slug` = VALUES(`slug`),
  `excerpt` = VALUES(`excerpt`),
  `content` = VALUES(`content`),
  `meta_title` = VALUES(`meta_title`),
  `meta_description` = VALUES(`meta_description`);
